DROP TABLE IF EXISTS `eventos`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `eventos` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `cliente_id` bigint unsigned NOT NULL,
  `fecha` date NOT NULL,
  `hora_recepcion` time DEFAULT NULL,
  `hora_inicio` time DEFAULT NULL,
  `horas_duracion` decimal(4,1) NOT NULL DEFAULT '5',
  `tipo_evento` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `nombre_festejado` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `color_manteleria` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `color_cubre_mantel` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `color_monos` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `color_camino_mesa` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `estado` enum('cotizacion','confirmado','finalizado','cancelado') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'cotizacion',
  `cerrado_por` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `titulo` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `notas` text COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`) /*T![clustered_index] CLUSTERED */,
  KEY `eventos_cliente_id_foreign` (`cliente_id`),
  KEY `eventos_fecha_estado_index` (`fecha`,`estado`),
  CONSTRAINT `eventos_cliente_id_foreign` FOREIGN KEY (`cliente_id`) REFERENCES `clientes` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci AUTO_INCREMENT=937665;
